DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.qa_baseline_functions b LEFT JOIN pg_namespace n ON n.nspname=b.nspname LEFT JOIN pg_proc p ON p.pronamespace=n.oid AND p.proname=b.proname AND pg_get_function_identity_arguments(p.oid)=b.args WHERE p.oid IS NULL OR pg_get_functiondef(p.oid) IS DISTINCT FROM b.definition OR p.proowner IS DISTINCT FROM b.proowner OR p.proacl IS DISTINCT FROM b.proacl) THEN RAISE EXCEPTION 'baseline definition owner ACL mismatch'; END IF;
 IF to_regclass('aurea_private.privacy_publications_v1') IS NOT NULL OR to_regclass('aurea_private.privacy_cycle_seals_v1') IS NOT NULL OR to_regprocedure('aurea_private.seal_privacy_cycle_v1()') IS NOT NULL OR to_regprocedure('aurea_private.privacy_publishable_v1(bigint,bigint,bigint)') IS NOT NULL OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='privacy_seal_on_close_v1') THEN RAISE EXCEPTION 'migration objects remain'; END IF;
 IF EXISTS(SELECT * FROM public.qa_before_answers EXCEPT SELECT * FROM aurea_private.response_answers) OR EXISTS(SELECT * FROM aurea_private.response_answers EXCEPT SELECT * FROM public.qa_before_answers) THEN RAISE EXCEPTION 'answers changed'; END IF;
 IF EXISTS(SELECT * FROM public.qa_before_responses EXCEPT SELECT * FROM aurea_private.responses) OR EXISTS(SELECT * FROM aurea_private.responses EXCEPT SELECT * FROM public.qa_before_responses) THEN RAISE EXCEPTION 'responses changed'; END IF;
 IF EXISTS(SELECT * FROM public.qa_before_digests EXCEPT SELECT * FROM aurea_private.weekly_report_digests) OR EXISTS(SELECT * FROM aurea_private.weekly_report_digests EXCEPT SELECT * FROM public.qa_before_digests) THEN RAISE EXCEPTION 'digests changed'; END IF;
END $$;
SELECT 'PASS complete rollback: six exact definitions, owner, ACL, removed objects, unchanged original answers/responses/digests';

